import{_ as a,H as p,f as l,i as t}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"07 | 云原生（上）：云原生选型是否能够降本增效？","description":"","frontmatter":{},"headers":[{"level":2,"title":"大数据和云原生","slug":"大数据和云原生","link":"#大数据和云原生","children":[]},{"level":2,"title":"云原生大数据方案的核心考量","slug":"云原生大数据方案的核心考量","link":"#云原生大数据方案的核心考量","children":[{"level":3,"title":"成本考量：并不总是最划算","slug":"成本考量-并不总是最划算","link":"#成本考量-并不总是最划算","children":[]},{"level":3,"title":"弹性优势：应对业务峰谷","slug":"弹性优势-应对业务峰谷","link":"#弹性优势-应对业务峰谷","children":[]},{"level":3,"title":"运维优势：专注业务价值","slug":"运维优势-专注业务价值","link":"#运维优势-专注业务价值","children":[]},{"level":3,"title":"技术考量：持续创新、技术锁定与性能调优","slug":"技术考量-持续创新、技术锁定与性能调优","link":"#技术考量-持续创新、技术锁定与性能调优","children":[]},{"level":3,"title":"数据安全与合规挑战","slug":"数据安全与合规挑战","link":"#数据安全与合规挑战","children":[]}]},{"level":2,"title":"课程总结","slug":"课程总结","link":"#课程总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"大数据应用实战/07｜云原生（上）：云原生选型是否能够降本增效？.md","filePath":"大数据应用实战/07｜云原生（上）：云原生选型是否能够降本增效？.md","lastUpdated":1795555553000}'),i={name:"大数据应用实战/07｜云原生（上）：云原生选型是否能够降本增效？.md"};function r(n,e,o,s,h,c){return p(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="_07-云原生-上-云原生选型是否能够降本增效" tabindex="-1">07 | 云原生（上）：云原生选型是否能够降本增效？ <a class="header-anchor" href="#_07-云原生-上-云原生选型是否能够降本增效" aria-label="Permalink to &quot;07 | 云原生（上）：云原生选型是否能够降本增效？&quot;">​</a></h1><p>你好，我是曹犟。</p><p>在前面几节课中，我们分别学习了大数据系统的整体架构设计、数据采集、传输、存储和计算等核心环节，在这个过程中，我们提到的绝大部分开源组件，都有公有云供应商提供云原生的部署方案。</p><p>云原生也是当下一个非常重要的技术潮流，它对于我们整个技术方案的整体设计、软硬件以及运维成本，都有直接的影响。因此，我们会花两节课的篇幅，专门来讨论一下大数据系统的云原生选型。今天我们先讨论一下，什么是云原生大数据，以及在做云原生大数据设计时应该考虑哪些问题。</p><h2 id="大数据和云原生" tabindex="-1">大数据和云原生 <a class="header-anchor" href="#大数据和云原生" aria-label="Permalink to &quot;大数据和云原生&quot;">​</a></h2><p>在讨论云原生大数据之前，我们需要先明确什么是云原生。</p><p>云原生不仅仅是把应用部署在云上那么简单。它是一种构建和运行应用的方法论，充分利用了云计算的弹性、分布式、自动化等特性。</p><p>当下的云原生技术，以容器为交付单位，以微服务拆解复杂业务，以声明式 API 与不可变基础设施确保一致性，再配合 DevOps 技术，来通过自动化编排与自愈能力实现快速迭代、弹性伸缩和故障自愈。通过服务网格化和完备的可观测性体系，如日志、指标、监控等，云原生把环境差异与运维复杂度“平台化”，让团队聚焦于业务价值而非底层细节。</p><p>从这个角度来看，大数据和云原生并不是互斥的概念，它们之间天然就是 “搭档关系”。大数据关注的是数据处理——如何采集、存储、分析海量、多样化、快速生成的数据，并从中挖掘价值；云原生关注的是应用构建与部署方式——如何让应用在云环境中更高效、弹性、可扩展地运行。</p><p>简单来说，云原生为大数据提供了理想的运行环境，大数据则为云原生赋予了更丰富的应用场景。举个例子，过往在服务很多国央企类客户的过程中，我发现他们 IT 类项目的立项建设习惯，都是先立项建设自己的私有云或混合云，再立项完成主流大数据系统部署，最后才启动具体应用场景的探索与落地。</p><p>云原生也给大数据系统带来了资源调度与运维方面的巨大收益。</p><p>云原生天生支持弹性伸缩，正好满足大数据计算在不同阶段对资源的动态需求。例如 Spark、Flink 等主流大数据框架都可以直接在云原生集群上按需分配计算资源。大数据任务往往是批处理或流处理，运行时间不均衡，云原生的动态调度可以让空闲资源被其他服务复用，降低成本。</p><p>云原生的容器化打包（Docker）和编排（K8s）也让大数据平台的部署、升级、回滚更标准化、自动化，减少了不同环境间的差异问题，避免了一个系统开发出来，“我这能跑，你那里不能跑”的问题。</p><p>云原生的对象存储（S3、GCS、OSS）结合数据湖技术（Iceberg、Delta Lake）也提供了一种可选的高可扩展性、低成本的存储方案。</p><p>对于一个大数据系统，是否应用“云原生技术”不是一个非黑即白的单选题。实践中，大数据系统适用云原生技术是一个灰度的过程，从轻到重可以分成几个不同层级。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/07/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/07/1.png" alt=""></a></p><p>最简单的层级是在基础设施层面，使用云厂商提供的计算、存储、网络资源，而不是自己采购硬件。这些资源可以按需申请和释放，不需要提前采购和部署，就能实现硬件层面上的弹性伸缩。</p><p>第二个层级则是在平台服务层面，使用云厂商提供的托管大数据组件，比如 AWS 的 EMR、腾讯云的托管 Doris、Kafka 等。这些服务或者是基于云厂商自研组件，或者是基于开源的大数据组件进行的部署，由云厂商负责解决部署、监控、升级、扩缩容等运维问题。</p><p>第三个层级则是在数据系统层面，使用云原生的整体性的数仓、数据湖系统等，如Snowflake、Databricks 等。相比第二层级，这个层级的厂商提供的是从数据准备、建模、开发的一体化解决方案，不再需要使用者用各种组件来组装搭建。</p><p>第四个层级则是在应用层面，直接使用云原生的大数据 SaaS 产品，如 Google Analytics、Amplitude、神策分析 SaaS 版等。这些 SaaS 产品连应用场景都做好了抽象和约束，做到了自动化的申请、计费，开箱即用。</p><p>那么，对于很多刚开始构建大数据系统的团队来说，一个必须回答的问题是：在构建自己的大数据系统时，要使用哪一层级的云原生技术？云原生真的能够降本增效吗？</p><h2 id="云原生大数据方案的核心考量" tabindex="-1">云原生大数据方案的核心考量 <a class="header-anchor" href="#云原生大数据方案的核心考量" aria-label="Permalink to &quot;云原生大数据方案的核心考量&quot;">​</a></h2><p>基于我多年的实践经验，云原生方案在某些场景下确实能带来实实在在的价值，但是有些时候则需要仔细权衡。让我们从以下几个方面来讨论。</p><h3 id="成本考量-并不总是最划算" tabindex="-1">成本考量：并不总是最划算 <a class="header-anchor" href="#成本考量-并不总是最划算" aria-label="Permalink to &quot;成本考量：并不总是最划算&quot;">​</a></h3><p>传统的自建模式是典型的资本性支出模式。你需要一次性投入大量资金购买硬件，但这些硬件的利用率往往不高。</p><p>我记得在百度的时候，为了应对高峰，大部分在线服务系统节点的 CPU Idle 都保持在 90% 以上，也就是说，90% 的计算资源是闲置的，但我们还是要为这些闲置资源付出机房、电力、运维的成本。Hadoop 集群的资源闲置率会好一些，但是大部分情况闲置率也在 70% 以上。</p><p>云原生则是运营性支出模式。你只需要为实际使用的资源付费。更重要的是，通过合理使用竞价实例、预留实例等定价模式，成本可以进一步降低。同时，通过订阅的方式，云原生把一次性硬件采购的财务压力分散到不同年份，对于很多现金流紧张的创业公司是很好的现金流管控方案。</p><p>但是，在成本上，云原生方案并不永远是最划算的。有些时候一些 IDC 能够提供远比公有云更具有优势的硬件成本方案，只不过需要我们自己来解决部署和运维的问题。</p><p>还有一个常见误区，就是以为云原生程度越高，成本上就越有优势。</p><p>我们以上面描述的云原生四个不同层级为例。从底下上，需要使用者介入的部分越来越少，维护起来越来越方便，但是反过来，不仅适应的场景灵活性也越来越低，成本也可能会越来越高。例如，当处理相同数据流量时，自己在公有云买虚拟机搭建 Kafka，和使用公有云提供的托管 Kafka 服务相比，在很多时候，硬件成本可以相差十倍。</p><p>当然，从商业的角度来看，这个也是可以理解的，毕竟越往上，集成度就越好，需要使用者付出的维护成本也会越低，这些成本都会通过其它方式体现出来。</p><p>使用云服务的时候，也需要我们建立成本监控体系，实时监控各项服务的费用，设置预算警报。根据负载特点，选择按需、预留、竞价等不同的定价模式。另外也建议你定期优化资源使用，清理不用的资源，调整过度配置的实例。</p><p>所以，云原生并不总是具有成本优势的，在这方面需要根据自己的业务情况、财务需求而定。技术团队是必须要有成本意识的，在架构设计时就需要考虑成本因素。</p><h3 id="弹性优势-应对业务峰谷" tabindex="-1">弹性优势：应对业务峰谷 <a class="header-anchor" href="#弹性优势-应对业务峰谷" aria-label="Permalink to &quot;弹性优势：应对业务峰谷&quot;">​</a></h3><p>业务负载的波动性是大数据系统面临的普遍挑战。</p><p>比如，电商平台在双十一期间，需要采集核处理的数据量可能是平时的 10 倍。如果按照峰值来规划自建集群，平时就会有大量资源闲置。如果按照平均值规划，峰值时又处理不过来。我们在服务很多选择了私有化部署方案的客户时，都会面临要在双十一等流量高峰前进行扩容，高峰结束后进行缩容这样的运维需求。这些运维操作都是需要提供额外人力的，最终也会体现在客户的账单上。</p><p>云原生的弹性伸缩能力可以很好地解决这个问题。你可以设置自动伸缩规则，根据负载自动增减节点。在业务高峰时快速扩容，在业务低谷时及时缩容。后面我会用一个真实的案例来对此做进一步说明。</p><h3 id="运维优势-专注业务价值" tabindex="-1">运维优势：专注业务价值 <a class="header-anchor" href="#运维优势-专注业务价值" aria-label="Permalink to &quot;运维优势：专注业务价值&quot;">​</a></h3><p>虽然各种开源大数据技术使得大数据的技术门槛大大降低，但是运维大数据集群依然是一件非常复杂的事情。我们需要处理硬件故障、系统升级、性能调优、安全补丁等各种问题。</p><p>根据我的经验，一个 50 台左右的中等规模的大数据集群，至少需要 3 到 5 个专职运维人员，并且这些人员需要具备一定的技术经验。</p><p>使用云原生的托管服务，这些运维工作主要都由云厂商承担了。我们的团队可以把精力放在业务逻辑上，而不是基础设施上，更好地服务业务。比如，使用 AWS 的 EMR 服务，我们不需要关心 Hadoop 的版本升级、组件的兼容性、集群的高可用配置等问题。这些都由 AWS 来保证。我们只需要根据业务的需求提交计算任务，等待结果就好。</p><p>当然，正如云厂商的托管运维服务，是需要额外的成本的，这些就需要仔细权衡。</p><h3 id="技术考量-持续创新、技术锁定与性能调优" tabindex="-1">技术考量：持续创新、技术锁定与性能调优 <a class="header-anchor" href="#技术考量-持续创新、技术锁定与性能调优" aria-label="Permalink to &quot;技术考量：持续创新、技术锁定与性能调优&quot;">​</a></h3><p>云厂商在大数据技术上的投入是巨大的。他们不仅提供开源组件的托管服务，还会推出很多创新的产品。比如，Snowflake 所提供的完整的数据解决方案，就是我们自建的时候很难实现的能力。更重要的是，云厂商会持续迭代优化。新的功能、更好的性能、更低的成本，这些改进我们都可以直接享受到，而不需要自己去升级改造。</p><p>使用云厂商的专有服务，可能会造成技术锁定。如果将来想要迁移到其它云或者回到自建，成本会很高。</p><p>所以，在使用云服务的时候，有这样几条最佳实践建议供参考：</p><ul><li><p>要优先使用开源标准，比如使用标准的 SQL 接口，而不是某家公有云厂商专有的查询语言。</p></li><li><p>要做好架构分层，将业务逻辑和基础设施分离，降低耦合度。</p></li><li><p>保持多云能力，关键系统要有多云部署的能力，避免过度依赖单一云厂商。神策在与几家国内的公有云厂商谈判的时候，就是因为我们的服务主要使用公有云的底层基础设施，对特定公有云没有依赖性，在不同公有云之间迁移技术上是可行的，所以获取了相当不错的折扣。</p></li></ul><p>在云上，我们失去了对底层硬件的控制，性能调优变得更加困难。所以，我们自己也需要具有在云上进行性能调优的基本能力。例如，选择合适的实例类型，不同的实例类型有不同的性能特点，要根据工作负载来选择。优化数据布局，合理使用数据分区、缓存等策略。利用云原生特性，比如使用 S3 的范围读取、并行下载等特性来优化我们的性能。</p><p>当然，对于大客户，云厂商通常会提供技术支持，帮助优化性能，只不过很多时候求人不如求己。</p><h3 id="数据安全与合规挑战" tabindex="-1">数据安全与合规挑战 <a class="header-anchor" href="#数据安全与合规挑战" aria-label="Permalink to &quot;数据安全与合规挑战&quot;">​</a></h3><p>这方面也是很多企业，特别是金融、医疗等行业，非常关心的问题：数据上云后的是否安全、是否合规？</p><p>一方面，我们当然要选择合规的云厂商和区域。比如在中国，要选择有相关牌照的云厂商，避免法规上的合规风险。</p><p>另一方面，我们也不能 100% 依赖云厂商。在技术上，我们自己也要采用加密存储和传输等方案，敏感数据要进行脱敏处理。</p><p>同时，使用专有云或混合云架构在很多时候也是一个必须的选择。对于特别敏感的数据，或者有合规要求的数据，是可以保留在本地的。敏感数据在本地，其他数据上云，是神策服务的很多客户现实上采取的方案。当然，建立完善的访问控制和审计机制也是必不可少的。</p><h2 id="课程总结" tabindex="-1">课程总结 <a class="header-anchor" href="#课程总结" aria-label="Permalink to &quot;课程总结&quot;">​</a></h2><p>今天这节课，我们深入探讨了云原生技术在大数据系统中的应用。</p><p>首先，我们明确了云原生不仅仅是把应用部署在云上，而是一种充分利用云计算特性的方法论。大数据和云原生是天然的搭档关系——云原生为大数据提供理想的运行环境，大数据为云原生赋予丰富的应用场景。</p><p>之后的重点是了解云原生大数据系统的四个层级，从基础设施层面到应用层面，云原生程度逐步提高。每个层级都有其适用场景，越往上层，使用者介入越少，但灵活性降低，成本可能增加。</p><p>最后，我们从成本、弹性、运维、技术、安全合规五个关键维度分析了云原生方案的核心考量。</p><p>希望你能够意识到，选择云原生方案不是非黑即白的决定，而是需要根据自身的业务特点、技术能力、成本预算等多方面因素综合考虑。</p><p>如果你是数据开发工程师，还需要重点关注以下方面。了解云原生的生态和常见设计模式，学会利用云原生的特性来进行性能优化，在系统设计时要有明确的 ROI 思维，不盲目追求新技术。能够准确评估业务的峰谷特征，设计合理的扩缩容策略，为突发流量预留应急方案。避免过度依赖单一云厂商，保持关键数据和逻辑的可迁移性，定期评估供应商的服务质量和成本。</p><p>如果你是数据产品经理，则要在规划云原生大数据产品时，计算清楚云原生方案的总体拥有成本，考虑迁移成本和长期运营成本，提前了解行业的合规要求。与法务、安全团队充分沟通，在产品设计初期就考虑数据分级和隔离。</p><p>最后，我准备了一个表格，总结了本节课中的部分课程内容，希望能够帮助你复习和总结。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/07/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/07/2.png" alt=""></a></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ul><li><p>你的组织目前是使用云原生还是自建大数据系统？选择的主要考虑因素是什么？如果有机会重新选择，你会做出不同的决定吗？</p></li><li><p>假设你负责一个电商平台的大数据系统架构设计，日常数据量约为 10 万条 / 天，但在双十一期间会飙升 10 倍。请问你会如何选择云原生的方案来应对这个弹性需求？需要考虑哪些关键因素？</p></li><li><p>如果你需要设计一个混合云架构的大数据系统，其中涉及金融交易数据（高度敏感）和用户行为数据（相对不敏感）。你会如何设计这个架构？哪些数据放在本地，哪些上云？如何确保两部分数据能够协同工作？</p></li></ul><p>欢迎在留言区分享你的经验和思考。对于课程中一些没能展开的内容，如果希望有更深入的了解，也欢迎留言与我直接交流。</p>',67)])])}const _=a(i,[["render",r]]);export{u as __pageData,_ as default};
